hardware:
body: dial
doctrine: thin-client
central: { link: wifi, heartbeat_hz: 10, timeout_ms: 500 }
mcu:
  reflex: { chip: esp32s3, module: N16R8, reserved_gpio: [26-37] }
  face:   { chip: rpi_zero_2w, os: bookworm-lite, location: head }
buses:
  servo_bus: { host: reflex, uart: 1, tx: 17, rx: 18, baud: 1000000, half_duplex: true }
  i2c0:      { host: reflex, sda: 8,  scl: 9,  hz: 400000 }
  i2c1_smb:  { host: reflex, sda: 10, scl: 11, hz: 100000 }
  link:      { reflex: { uart: 2, tx: 15, rx: 16 }, face: { uart: 0, tx: 14, rx: 15 }, baud: 921600 }
  spi0:      { host: face, mosi: 10, sclk: 11, cs: 8, hz: 62500000 }
  i2s:       { host: face, bclk: 18, lrclk: 19, din: 20, dout: 21, rate: 48000 }
  csi:       { host: face, port: cam0 }
servos:
  - { id: 1, name: pan,  model: sts3215, center: 2048, min: 341,  max: 3755, rest: 2048 }
  - { id: 2, name: tilt, model: sts3215, center: 2048, min: 1707, max: 2503, rest: 1764 }
servo_limits: { temp_warn_c: 65, temp_trip_c: 70, rest_torque_pct: 20, slow_dps: 30 }
peripherals:
  - { name: tof_front,  part: vl53l8cx,  bus: i2c0, addr: 0x29, lpn: 4, int: 5, role: presence }
  - { name: charger,    part: bq25798,   bus: i2c0, addr: 0x6B, int: 6, ce: 7 }
  - { name: gauge,      part: sbs_pack,  bus: i2c1_smb, addr: 0x0B }
  - { name: servo_pwr,  part: efuse,     en: 12, fault: 13 }
  - { name: face_wake,  gpio: 14, to: face.gpio3 }
  - { name: status_led, part: ws2812,    gpio: 48 }
  - { name: display,    part: st7789v,   bus: spi0, dc: 25, rst: 24, bl_pwm: 13, size: 320x240, rotation: 90 }
  - { name: mics,       part: ics43434,  bus: i2s, count: 2, sel: [gnd, 3v3], spacing_mm: 92 }
  - { name: speaker_amp, part: max98357a, bus: i2s, sd: 16 }
  - { name: camera,     part: imx708,    bus: csi }
sensing_rule: { drives: false, forward_lidar: tof_front, drop_off: not_applicable_fixed_base }
safety:
  triggers: [heartbeat_lost, soc_below_15, vbat_below_10v5, servo_overtemp, efuse_fault]
  routine:  [stop, brake, wait_2s, slow_to_rest, torque_low, face_sleepy]
  resume:   fresh_command_only
